function renderHistory(){const canvas=$('#history-chart'),empty=$('#history-empty');if(!canvas)return;const rows=state.asset==='btc'?state.history.btc:state.history.usd;if(!rows?.length){empty.textContent='No hay datos históricos disponibles.';return}empty.textContent='';const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(300,rect.width),h=Math.max(160,rect.height);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const pad={l:12,r:12,t:14,b:22},vals=rows.map(x=>x.v),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;ctx.strokeStyle='rgba(145,167,178,.16)';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=pad.t+(h-pad.t-pad.b)*i/3;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke()}const pts=rows.map((p,i)=>({x:pad.l+(w-pad.l-pad.r)*(i/Math.max(1,rows.length-1)),y:pad.t+(h-pad.t-pad.b)*(1-(p.v-min)/range)}));const grad=ctx.createLinearGradient(0,pad.t,0,h-pad.b);grad.addColorStop(0,'rgba(105,226,181,.23)');grad.addColorStop(1,'rgba(105,226,181,0)');ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(pts[pts.length-1].x,h-pad.b);ctx.lineTo(pts[0].x,h-pad.b);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#69e2b5';ctx.lineWidth=2;ctx.stroke();const last=rows[rows.length-1],first=rows[0],pct=first.v?(last.v/first.v-1)*100:0;$('#history-current').textContent=state.asset==='btc'?fmt(last.v):fmt(last.v,'ARS');$('#history-change').textContent=(pct>=0?'+':'')+num(pct)+'% en el período';ctx.fillStyle='rgba(145,167,178,.8)';ctx.font='9px system-ui';ctx.fillText(new Date(first.t).toLocaleDateString('es-AR'),pad.l,h-6);const end=new Date(last.t).toLocaleDateString('es-AR');ctx.fillText(end,w-pad.r-ctx.measureText(end).width,h-6)}
function renderSpread(){const root=$('#spread-list');if(!root)return;const keys=['oficial','blue','bolsa','contadoconliqui'];const labels={oficial:'Oficial',blue:'Blue',bolsa:'MEP',contadoconliqui:'CCL'};const base=state.fx.find(x=>x.casa==='oficial');root.innerHTML=keys.map(k=>{const x=state.fx.find(v=>v.casa===k);if(!x)return '<div class="spread-row"><span>'+labels[k]+'</span><strong>—</strong><small>Dato no disponible</small></div>';const gap=base&&k!=='oficial'&&Number(base.venta)>0?(Number(x.venta)/Number(base.venta)-1)*100:null;return '<div class="spread-row"><span>'+labels[k]+' · venta</span><strong>'+fmt(x.venta,'ARS')+'</strong><small>'+(gap===null?'Referencia base':(gap>=0?'+':'')+num(gap)+'% vs. oficial')+'</small></div>'}).join('')}

function setClock(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString('es-AR');$('#market-date').textContent=d.toLocaleDateString('es-AR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'})}
function makeChart(asset){const btc=asset==='btc',symbol=btc?'BINANCE%3ABTCUSDT':'FX_IDC%3AUSDARS',url='https://s.tradingview.com/widgetembed/?symbol='+symbol+'&interval=60&hidesidetoolbar=0&symboledit=1&saveimage=0&toolbarbg=07111f&theme=dark&style=1&timezone=America%2FArgentina%2FBuenos_Aires&withdateranges=1&hideideas=1&locale=es';$('#tradingview-chart').src=url;$('#chart-title').textContent=btc?'Bitcoin · Dólar estadounidense':'Dólar estadounidense · Peso argentino';$('#chart-subtitle').textContent=(btc?'BINANCE:BTCUSDT':'FX_IDC:USDARS')+' · Gráfico provisto por TradingView';$('#open-chart').href='https://www.tradingview.com/chart/?symbol='+ (btc?'BINANCE%3ABTCUSDT':'FX_IDC%3AUSDARS');$('#chart-disclaimer').textContent=btc?'BTCUSDT representa un mercado cripto.':'USDARS es una referencia de mercado; no equivale al dólar blue, MEP ni CCL.'}
function setNews(asset){const btc=asset==='btc';const links=btc?[['GOOGLE NEWS','Últimas noticias de Bitcoin','https://news.google.com/search?q=Bitcoin&hl=es-419&gl=AR&ceid=AR%3Aes-419','Cobertura actualizada ↗'],['COINDESK','Noticias del mercado cripto','https://www.coindesk.com/','Fuente especializada ↗'],['REUTERS','Mercados y monedas globales','https://www.reuters.com/markets/currencies/','Contexto internacional ↗']]:[['GOOGLE NEWS','Últimas noticias del dólar en Argentina','https://news.google.com/search?q=d%C3%B3lar+Argentina+econom%C3%ADa&hl=es-419&gl=AR&ceid=AR%3Aes-419','Cobertura actualizada ↗'],['ÁMBITO','Dólar y mercados argentinos','https://www.ambito.com/finanzas','Actualidad financiera ↗'],['REUTERS','Mercados y monedas globales','https://www.reuters.com/markets/currencies/','Contexto internacional ↗']];$('#news-description').textContent=btc?'Cobertura relacionada con Bitcoin y activos digitales.':'Cobertura relacionada con dólar, economía y mercados argentinos.';$('#news-links').innerHTML=links.map(x=>'<a href="'+x[2]+'" target="_blank" rel="noopener noreferrer"><span class="news-source">'+x[0]+'</span><b>'+x[1]+'</b><small>'+x[3]+'</small></a>').join('')}
function renderTicker(){const blue=state.fx.find(v=>v.casa==='blue'),mep=state.fx.find(v=>v.casa==='bolsa'),ccl=state.fx.find(v=>v.casa==='contadoconliqui');$('#ticker-btc').textContent=state.btc?fmt(state.btc.usd):'—';$('#ticker-blue').textContent=blue?fmt(blue.venta,'ARS'):'—';$('#ticker-mep').textContent=mep?fmt(mep.venta,'ARS'):'—';$('#ticker-ccl').textContent=ccl?fmt(ccl.venta,'ARS'):'—'}
function renderActiveQuote(){renderTicker();const btc=state.asset==='btc';if(btc&&state.btc){const x=state.btc;$('#active-quote-label').textContent='BITCOIN · BTC/USD';$('#active-price').textContent=fmt(x.usd);const ch=Number(x.usd_24h_change);$('#active-change').textContent='24 h: '+(Number.isFinite(ch)?(ch>=0?'+':'')+num(ch)+'%':'s/d')+' · CoinGecko';$('#quote-secondary-label').textContent='MÁXIMO / MÍNIMO 24 H';$('#quote-secondary').textContent=fmt(x.high_24h)+' / '+fmt(x.low_24h);$('#quote-secondary-detail').textContent='Rango diario reportado';$('#market-action').textContent='Comparar mercados de BTC ↗';$('#market-action').href='https://www.coingecko.com/es/monedas/bitcoin#markets';}else if(!btc){const x=state.fx.find(v=>v.casa==='blue')||state.fx.find(v=>v.casa==='oficial');$('#active-quote-label').textContent=x&&x.casa==='blue'?'DÓLAR BLUE · ARS/USD':'DÓLAR OFICIAL · ARS/USD';$('#active-price').textContent=x?fmt(x.venta,'ARS'):'No disponible';$('#active-change').textContent=x?'Compra '+fmt(x.compra,'ARS')+' · DolarAPI':'Proveedor no disponible';$('#quote-secondary-label').textContent='MEP / CCL';const mep=state.fx.find(v=>v.casa==='bolsa'),ccl=state.fx.find(v=>v.casa==='contadoconliqui');$('#quote-secondary').textContent=(mep?fmt(mep.venta,'ARS'):'—')+' / '+(ccl?fmt(ccl.venta,'ARS'):'—');$('#quote-secondary-detail').textContent='Venta reportada';$('#market-action').textContent='Ver cotizaciones argentinas ↓';$('#market-action').href='#fx-reference'}$('#quote-updated').textContent=state.updated?state.updated.toLocaleTimeString('es-AR'):'—';const ref=state.fx.find(v=>v.casa==='blue')||state.fx.find(v=>v.casa==='oficial');$('#local-reference').textContent=ref?fmt(ref.venta,'ARS'):'—';$('#local-reference-detail').textContent=ref?(ref.casa==='blue'?'Dólar blue · venta':'Dólar oficial · venta'):'DolarAPI sin respuesta';updateConversion()}
function renderRates(){const labels={oficial:'Dólar oficial',blue:'Dólar blue',bolsa:'Dólar MEP',contadoconliqui:'Dólar CCL',mayorista:'Dólar mayorista',tarjeta:'Dólar tarjeta'};const keys=Object.keys(labels);const html=keys.map(k=>{const x=state.fx.find(v=>v.casa===k);return x?'<article class="rate-card"><span>'+labels[k]+'</span><strong>'+fmt(x.venta,'ARS')+'</strong><small>Compra '+fmt(x.compra,'ARS')+'<br>Actualizado: '+(x.fechaActualizacion?new Date(x.fechaActualizacion).toLocaleString('es-AR'):'sin hora')+'</small></article>':'<article class="rate-card"><span>'+labels[k]+'</span><strong>—</strong><small>Dato no disponible</small></article>'}).join('');$('#fx').innerHTML=html}
async function fetchBtc(){const urls=['https://api.coingecko.com/api/v3/coins/bitcoin?localization=false&tickers=false&market_data=true&community_data=false&developer_data=false'];let last;for(const url of urls){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();const m=d.market_data;if(!m)throw Error('Sin datos de mercado');state.btc={usd:m.current_price.usd,usd_24h_change:m.price_change_percentage_24h,high_24h:m.high_24h.usd,low_24h:m.low_24h.usd};return}catch(e){last=e}}throw last||Error('Proveedor no disponible')}
async function fetchFx(){const r=await fetch('https://dolarapi.com/v1/dolares',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();if(!Array.isArray(data))throw Error('Formato inesperado');state.fx=data;renderRates()}
async function refresh(){const status=$('#connection-status');status.textContent='Actualizando…';const outcomes=await Promise.allSettled([fetchBtc(),fetchFx()]);state.updated=new Date();renderActiveQuote();renderSpread();checkAlerts();const ok=outcomes.some(x=>x.status==='fulfilled');status.textContent=ok?'Fuentes consultadas':'Fuentes no disponibles';if(outcomes.every(x=>x.status==='rejected'))$('#active-change').textContent='No se pudo actualizar; intentá nuevamente.'}
function selectAsset(asset){state.asset=asset;document.querySelectorAll('.asset-tab').forEach(b=>b.classList.toggle('active',b.dataset.asset===asset));makeChart(asset);setNews(asset);renderActiveQuote();fetchHistory()}
function updateConversion(){const amount=Math.max(0,Number($('#convert-amount').value)||0),from=$('#convert-from').value,to=$('#convert-to').value,btc=Number(state.btc?.usd)||0;const blue=state.fx.find(v=>v.casa==='blue')||state.fx.find(v=>v.casa==='oficial');const buy=Number(blue?.compra)||0,sell=Number(blue?.venta)||0;let result=0,valid=amount>0,detail='';if(from===to){result=amount;detail='Misma moneda'}else if(from==='ARS'&&to==='USD'&&sell){result=amount/sell;detail='Dólar '+(blue?.casa==='blue'?'blue':'oficial')+' · venta'}else if(from==='USD'&&to==='ARS'&&buy){result=amount*buy;detail='Dólar '+(blue?.casa==='blue'?'blue':'oficial')+' · compra'}else if(from==='BTC'&&to==='USD'&&btc){result=amount*btc;detail='BTC/USD · CoinGecko'}else if(from==='USD'&&to==='BTC'&&btc){result=amount/btc;detail='BTC/USD · CoinGecko'}else if(from==='BTC'&&to==='ARS'&&btc&&buy){result=amount*btc*buy;detail='BTC/USD × dólar de compra'}else if(from==='ARS'&&to==='BTC'&&btc&&sell){result=amount/sell/btc;detail='Dólar de venta × BTC/USD'}else valid=false;valid=valid&&Number.isFinite(result)&&result>=0;$('#convert-result').textContent=valid?(to==='BTC'?num(result,8)+' BTC':fmt(result,to)): '—';$('#convert-detail').textContent=valid?detail+' · estimación sin comisiones':'Esperando cotizaciones válidas';state.conversion=valid?{amount,from,to,result}:null}
function swap(){const a=$('#convert-from'),b=$('#convert-to'),x=a.value;a.value=b.value;b.value=x;updateConversion()}
async function copyConversion(){if(!state.conversion){$('#ag-toast').textContent='Ingresá un importe y esperá las cotizaciones.';return}const c=state.conversion;const out=c.to==='BTC'?num(c.result,8)+' BTC':fmt(c.result,c.to);const text='Arteche Terminal · Conversión orientativa\n'+num(c.amount)+' '+c.from+' = '+out+'\nNo constituye una oferta ni ejecuta operaciones.';try{await navigator.clipboard.writeText(text);$('#ag-toast').textContent='Conversión copiada.'}catch{$('#ag-toast').textContent='No se pudo copiar desde este navegador.'}}
